#include "../line_scroll.h"
#include <cstdio>
#include <cstdlib>
using namespace Snatcher;
namespace {unsigned checks;void check(bool ok,const char* why){++checks;if(!ok){std::fprintf(stderr,"Line scroll: %s\n",why);std::exit(1);}}bool equal(const NativeLineScrollState&a,const NativeLineScrollState&b){return a.version==b.version&&a.mode==b.mode&&a.phase==b.phase&&a.lineEnabled==b.lineEnabled&&a.completed==b.completed&&a.active==b.active&&a.counterKnown==b.counterKnown&&a.lastGlobalCounter==b.lastGlobalCounter&&a.publishedPrefix==b.publishedPrefix&&a.counters==b.counters&&a.computed==b.computed&&a.published==b.published;}}
int main(){std::string error;NativeLineScroll scroll;check(scroll.tick(0,error)&&!scroll.state().active,"inactive tick does not create mode");scroll.start();check(scroll.state().publishedPrefix==128,"initial clear publishes128 source rows");check(scroll.tick(1,error)&&scroll.sourceX(8)==0,"mode start at odd global phase does not invent even update");check(scroll.tick(2,error)&&scroll.sourceX(8)==1&&scroll.sourceX(15)==1&&scroll.sourceX(16)==0,"first eight-row band at global even phase");check(scroll.tick(3,error)&&scroll.tick(4,error)&&scroll.sourceX(8)==2&&scroll.sourceX(16)==1&&scroll.sourceX(24)==1&&scroll.sourceX(25)==0,"second band follows global modulo4");check(scroll.tick(5,error)&&scroll.tick(6,error)&&scroll.sourceX(25)==1&&scroll.sourceX(36)==1&&scroll.sourceX(37)==0,"local six-update band independent of global modulo");
 scroll.start();for(unsigned n=1;n<=18;++n)check(scroll.tick(uint16_t(n),error),"eighteen source updates");const unsigned first[]={8,16,25,37,47,55,61,66,70},last[]={15,24,36,46,54,60,65,69,72},expected[]={9,4,3,2,1,1,1,1,1};for(unsigned i=0;i<9;++i)check(scroll.sourceX(first[i])==int(expected[i])&&scroll.sourceX(last[i])==int(expected[i]),"source band boundary and independent cadence");check(scroll.sourceX(7)==0&&scroll.sourceX(73)==0&&scroll.sourceX(135)==0&&scroll.sourceX(136)==0,"unmodified rows stay zero within and outside owned window");check(scroll.state().publishedPrefix==65,"last band publication covers65 owned plane-B words");
 NativeLineScroll resumed;check(resumed.restore(scroll.state(),error),"restore intermediate cadence");for(unsigned n=19;n<=2100;++n){check(scroll.tick(uint16_t(n),error)&&resumed.tick(uint16_t(n),error)&&equal(scroll.state(),resumed.state()),"saved cadence and row offsets continue exactly");}check(scroll.sourceX(8)==26,"ten-bit scroll wraps after1024 decrements");scroll.start();check(scroll.tick(65535,error)&&scroll.tick(0,error)&&scroll.sourceX(8)==1&&scroll.sourceX(16)==1&&scroll.sourceX(66)==1,"global16-bit wrap preserves modulo cadence");auto before=scroll.state(),bad=before;bad.counters[0]=6;check(!scroll.restore(bad,error)&&equal(before,scroll.state()),"invalid cadence rejected transactionally");bad=before;bad.publishedPrefix=64;check(!scroll.restore(bad,error)&&equal(before,scroll.state()),"impossible publication boundary rejected");bad=before;bad.computed[80]=bad.published[80]=1;check(!scroll.restore(bad,error),"unowned tail cannot acquire motion");bad=before;bad.published[0]^=1;check(!scroll.restore(bad,error),"unpublished changed source row is impossible");scroll.reset();check(!scroll.state().active&&scroll.sourceX(8)==0,"reset removes previous scene motion");for(unsigned mode:{4u,5u,6u}){check(scroll.start(mode,error),"start closed secondary family");NativeLineScroll other;for(unsigned n=1;n<=50;++n){check(scroll.tick(uint16_t(n+127),error),"family source update");check(other.restore(scroll.state(),error),"family typed state accepted");NativeLineScroll copy=scroll;check(copy.tick(uint16_t(n+128),error)&&other.tick(uint16_t(n+128),error)&&equal(copy.state(),other.state()),"family exact semantic continuation");}}
 scroll.start(4,error);for(unsigned n=1;n<=7;++n)scroll.tick(uint16_t(n),error);check(scroll.sourceX(8)==1023&&scroll.sourceX(119)==1023&&scroll.sourceX(120)==1023&&scroll.sourceX(127)==1023&&scroll.sourceX(128)==1023&&scroll.sourceX(135)==1022,"mode4 reversed five cadence bands");
 scroll.start(6,error);scroll.tick(1,error);check(scroll.sourceX(119)==0&&scroll.sourceX(120)==2&&scroll.sourceX(128)==2&&scroll.sourceX(129)==1022&&scroll.sourceX(135)==1022,"mode6 split bands and sign");for(unsigned n=1;n<512;++n)scroll.tick(uint16_t(n),error);check(scroll.sourceX(120)==0&&scroll.sourceX(129)==0,"mode6 two-pixel1024 wrap");
 scroll.start(5,error);scroll.tick(1,error);check(scroll.sourceX(55)==0&&scroll.sourceX(56)==8&&scroll.sourceX(59)==12&&scroll.sourceX(61)==8&&scroll.sourceX(64)==0&&scroll.sourceX(80)==1022&&scroll.sourceX(104)==1020&&scroll.sourceX(120)==0&&scroll.state().publishedPrefix==112,"mode5 fixed distortion bands");for(unsigned n=0;n<7;++n)scroll.tick(2,error);check(scroll.state().lineEnabled,"distortion retained through seventh wait");scroll.tick(2,error);check(!scroll.state().lineEnabled&&scroll.state().phase==2&&scroll.sourceX(56)==0,"eighth wait switches to base scroll");for(unsigned n=0;n<13;++n)scroll.tick(3,error);check(scroll.state().lineEnabled&&scroll.state().phase==3&&scroll.sourceX(56)==8,"thirteen updates restore same distortion");for(unsigned n=0;n<6;++n)scroll.tick(4,error);check(scroll.state().active&&!scroll.state().completed,"distortion retains final sixth wait");scroll.tick(4,error);check(!scroll.state().active&&scroll.state().completed&&!scroll.state().lineEnabled,"seventh final wait emits source reset completion");auto finished=scroll.state();check(scroll.tick(99,error)&&equal(finished,scroll.state()),"completed owner stable until consumer resets");check(!scroll.start(7,error)&&equal(finished,scroll.state()),"outside closed family rejected transactionally");
 std::printf("Native line scroll: %u checks,0 failures\n",checks);return 0;}
